  erase_end_user: {"summary":"Erase every question that one end user asked, from every knowledge base of the project, together with their memories, the raw conversations behind those memories, and every replaced version, at once and with no way to restore it.","tag":"end-users","document":"api","access":"project","changesState":true,"dataAccess":null,"keyPermissions":[{"resource_kind":"knowledge_bases","level":"write","target":"every","resource_id_field":null,"only_with_field":null},{"resource_kind":"memory","level":"write","target":"every","resource_id_field":null,"only_with_field":null}],"inputSchema":{"type":"object","properties":{"project_id":{"type":"string","pattern":"^prj_[0-9a-f]{32}$"},"end_user_id":{"type":"string","x-himring-rules":[{"kind":"min_length","expects":">=1","message":"Send the ID that your system gives the end user."},{"kind":"max_length","expects":"<=200","message":"Shorten the end user ID to 200 characters or fewer."},{"kind":"check","expects":null,"message":"Remove the control characters from the end user ID."}]}},"required":["project_id","end_user_id"]},"outputSchema":{"type":"object","properties":{"end_user_id":{"type":"string"},"erased_questions":{"type":"number"},"knowledge_bases":{"type":"number"},"erased_memories":{"type":"number","description":"How many memories about the end user Himring erased."},"erased_messages":{"type":"number","description":"How many raw messages behind them Himring erased."}},"required":["end_user_id","erased_questions","knowledge_bases","erased_memories","erased_messages"]}},
