  export_memories: {"summary":"Download the memories of the Memory as one JSON file, or only those of one end user with end_user_id. A file holds at most 25000 memories and 32 MiB, and its next_after gives the after for the next part.","tag":"memory","document":"api","access":"project","changesState":false,"dataAccess":null,"keyPermissions":[{"resource_kind":"memory","level":"read","target":"every","resource_id_field":null,"only_with_field":null}],"inputSchema":{"type":"object","properties":{"project_id":{"type":"string","pattern":"^prj_[0-9a-f]{32}$"},"memory_id":{"type":"string","pattern":"^mem_[0-9a-f]{32}$"},"end_user_id":{"type":"string","minLength":1,"maxLength":512,"x-himring-rules":[{"kind":"max_length","expects":"<=512","message":"Shorten the owner ID to 512 characters or fewer."},{"kind":"check","expects":null,"message":"Remove the control characters from the owner ID."}]},"after":{"type":"string","pattern":"^mm_[0-9a-f]{32}$","description":"The next_after of the previous part, to continue the export."}},"required":["project_id","memory_id"],"additionalProperties":false},"outputSchema":null},
