  get_memory_webhook: {"summary":"Read the URL that receives the decisions of the Memory. The signing secret stays hidden.","tag":"memory","document":"api","access":"project","changesState":false,"dataAccess":null,"keyPermissions":[{"resource_kind":"memory","level":"read","target":"every","resource_id_field":null,"only_with_field":null}],"inputSchema":{"type":"object","properties":{"project_id":{"type":"string","pattern":"^prj_[0-9a-f]{32}$"},"memory_id":{"type":"string","pattern":"^mem_[0-9a-f]{32}$"}},"required":["project_id","memory_id"],"additionalProperties":false},"outputSchema":{"type":"object","properties":{"url":{"type":"string"},"created_at":{"type":"string"},"updated_at":{"type":"string"}},"required":["url","created_at","updated_at"]}},
