  restore_project: {"summary":"Restore a deleted project, with the databases and indexes that were deleted with it.","tag":"restore","document":"session","access":"project_owner","changesState":true,"dataAccess":null,"keyPermissions":null,"inputSchema":{"type":"object","properties":{"project_id":{"type":"string","pattern":"^prj_[0-9a-f]{32}$"}},"required":["project_id"],"additionalProperties":false},"outputSchema":{"type":"object","properties":{"id":{"type":"string"},"name":{"type":"string"},"region":{"type":"string"},"role":{"anyOf":[{"enum":["owner","member"],"type":"string"},{"type":"null"}]},"created_at":{"type":"string"},"deleted_at":{"anyOf":[{"type":"string"},{"type":"null"}]},"purge_after":{"anyOf":[{"type":"string"},{"type":"null"}]},"sirannon_url":{"type":"string"},"narsil_url":{"type":"string"}},"required":["id","name","region","role","created_at","deleted_at","purge_after","sirannon_url","narsil_url"]}},
