  send_memory_feedback: {"summary":"Tell Himring that a memory is right or wrong, for example after your agent used it. Himring changes nothing about the memory and learns its thresholds from the feedback.","tag":"memory","document":"api","access":"project","changesState":true,"dataAccess":null,"keyPermissions":[{"resource_kind":"memory","level":"read","target":"every","resource_id_field":null,"only_with_field":null}],"inputSchema":{"type":"object","properties":{"project_id":{"type":"string","pattern":"^prj_[0-9a-f]{32}$"},"memory_id":{"type":"string","pattern":"^mem_[0-9a-f]{32}$"},"stored_memory_id":{"type":"string","pattern":"^mm_[0-9a-f]{32}$"},"verdict":{"enum":["right","wrong"],"type":"string"},"recall_id":{"type":"string","pattern":"^rcl_[0-9a-f]{32}$"}},"required":["project_id","memory_id","stored_memory_id","verdict"]},"outputSchema":{"type":"object","properties":{"id":{"type":"string"},"stored_memory_id":{"type":"string"},"verdict":{"enum":["right","wrong"],"type":"string"},"created_at":{"type":"string"}},"required":["id","stored_memory_id","verdict","created_at"]}},
  set_memory_webhook: {"summary":"Send every decision of the Memory to your own URL as it happens, with the owner of its subject, so that you can route it to that owner. Each request carries the ID of the event, a timestamp, and an HMAC-SHA256 signature over the timestamp and the body, made with the signing secret in the response. Himring retries a failed delivery for 72 hours with growing waits. Calling this again replaces the URL and the secret.","tag":"memory","document":"api","access":"project","changesState":true,"dataAccess":null,"keyPermissions":[{"resource_kind":"memory","level":"write","target":"every","resource_id_field":null,"only_with_field":null}],"inputSchema":{"type":"object","properties":{"project_id":{"type":"string","pattern":"^prj_[0-9a-f]{32}$"},"memory_id":{"type":"string","pattern":"^mem_[0-9a-f]{32}$"},"url":{"type":"string","x-himring-rules":[{"kind":"max_length","expects":"<=2048","message":"Shorten the URL to 2048 characters or fewer."},{"kind":"url","expects":null,"message":"Send the URL of the webhook, such as https://example.com/himring."},{"kind":"check","expects":null,"message":"Send a URL that starts with https://."},{"kind":"check","expects":null,"message":"Leave the user name and the password out of the URL."}]}},"required":["project_id","memory_id","url"]},"outputSchema":{"type":"object","properties":{"url":{"type":"string"},"created_at":{"type":"string"},"updated_at":{"type":"string"},"signing_secret":{"type":"string","description":"The secret that signs every event. Himring shows it once, so store it now."}},"required":["url","created_at","updated_at","signing_secret"]}},
