  sign_in: {"summary":"Check an email address and a password, and start the second-factor step of the sign-in.","tag":"auth","document":"api","access":"public","changesState":true,"dataAccess":null,"keyPermissions":null,"inputSchema":{"type":"object","properties":{"email":{"type":"string","x-himring-rules":[{"kind":"max_length","expects":"<=254","message":"Shorten the email address to 254 characters or fewer."},{"kind":"regex","expects":"/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/","message":"Send an email address such as someone@example.com."}]},"password":{"type":"string","minLength":1,"maxLength":128,"x-himring-rules":[{"kind":"max_length","expects":"<=128","message":"Send a password of at most 128 characters."}]},"known_device_token":{"type":"string","minLength":1,"maxLength":1024,"pattern":"^[A-Za-z0-9_-]+$","x-himring-rules":[{"kind":"max_length","expects":"<=1024","message":"Send the known-device token exactly as Himring issued it."}]}},"required":["email","password"]},"outputSchema":{"anyOf":[{"type":"object","properties":{"state":{"const":"second_factor_required"},"challenge_token":{"type":"string"},"known_device_token":{"type":"string"}},"required":["state","challenge_token","known_device_token"]},{"type":"object","properties":{"state":{"const":"second_factor_setup_required"},"session_token":{"type":"string"},"known_device_token":{"type":"string"}},"required":["state","session_token","known_device_token"]}]}},
