  suggest_index_terms: {"summary":"Complete the start of a word from the words that a live index holds, most widely used first, with the number of records that hold each word. Each request counts as one search request, so send one when the typing pauses.","tag":"indexes","document":"api","access":"project","changesState":false,"dataAccess":null,"keyPermissions":[{"resource_kind":"indexes","level":"read","target":"resource","resource_id_field":"index_id","only_with_field":null}],"inputSchema":{"type":"object","properties":{"project_id":{"type":"string","pattern":"^prj_[0-9a-f]{32}$"},"index_id":{"type":"string","pattern":"^ix_[0-9a-f]{32}$"},"prefix":{"type":"string","description":"The start of a word, which the suggestions complete from the words that the index holds.","x-himring-rules":[{"kind":"min_length","expects":">=1","message":"Write the start of a word to complete."},{"kind":"max_length","expects":"<=64","message":"Shorten the prefix to 64 characters or fewer."},{"kind":"check","expects":null,"message":"Remove the control characters from the prefix."}]},"limit":{"anyOf":[{"type":"integer","minimum":1,"maximum":20},{"type":"string","pattern":"^\\d{1,9}$","x-himring-rules":[{"kind":"number","expects":"number","message":"Send the number of suggestions as a whole number."},{"kind":"min_value","expects":">=1","message":"Send the number of suggestions of at least 1."},{"kind":"max_value","expects":"<=20","message":"Send the number of suggestions of at most 20."}]}],"default":8}},"required":["project_id","index_id","prefix"]},"outputSchema":{"type":"object","properties":{"terms":{"type":"array","items":{"type":"object","properties":{"term":{"type":"string"},"record_count":{"type":"number"}},"required":["term","record_count"]}},"duration_ms":{"type":"number"}},"required":["terms","duration_ms"]}},
