  try_corrections: {"summary":"Try up to 10 proposed corrections in one background pass. Himring scores a field weight or a fusion setting on the live index at once, and builds a second index for each correction that changes the index, at most 2 in one pass, reusing the stored vector of every chunk whose text is unchanged. It discards every correction that lowers the held-back score. When automatic corrections are on for the knowledge base, it also promotes the best correction whose cause is known, whose held-back score holds, which raises the score of the tuning questions with confirmed passages, and which waits for no click.","tag":"knowledge-bases","document":"api","access":"project","changesState":true,"dataAccess":null,"keyPermissions":[{"resource_kind":"knowledge_bases","level":"write","target":"resource","resource_id_field":"knowledge_base_id","only_with_field":null}],"inputSchema":{"type":"object","properties":{"project_id":{"type":"string","pattern":"^prj_[0-9a-f]{32}$"},"knowledge_base_id":{"type":"string","pattern":"^kb_[0-9a-f]{32}$"},"correction_ids":{"type":"array","items":{"type":"string","pattern":"^cor_[0-9a-f]{32}$"},"minItems":1,"maxItems":10},"complete_index":{"type":"boolean","description":"true to build a complete second index for a chunking correction and swap to it, in place of changing the live index one file at a time.","default":false}},"required":["project_id","knowledge_base_id","correction_ids"]},"outputSchema":{"type":"object","properties":{"id":{"type":"string"},"trigger":{"enum":["requested","automatic"],"type":"string"},"mode":{"enum":["propose","try"],"type":"string"},"status":{"enum":["queued","running","done","failed"],"type":"string"},"complete_index":{"type":"boolean"},"before_scorecard_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"after_scorecard_id":{"anyOf":[{"type":"string"},{"type":"null"}]},"correction_ids":{"type":"array","items":{"type":"string"}},"failure_message":{"anyOf":[{"type":"string"},{"type":"null"}]},"requested_at":{"type":"string"},"started_at":{"anyOf":[{"type":"string"},{"type":"null"}]},"finished_at":{"anyOf":[{"type":"string"},{"type":"null"}]}},"required":["id","trigger","mode","status","complete_index","before_scorecard_id","after_scorecard_id","correction_ids","failure_message","requested_at","started_at","finished_at"]}},
  tune_memory: {"summary":"Start a tuning of the Memory now. Himring replays the labelled decisions with the probabilities that sorting stored, keeps a change to a threshold or a cue weight only when the held-back decisions come out right more often, and scores recall and judgement again. Himring also tunes by itself, in the background, as labelled decisions arrive. The call refuses with memory_tuning_has_no_new_input when a run would use nothing new, and returns the scores without queuing a second run while one is queued or working.","tag":"memory","document":"api","access":"project","changesState":true,"dataAccess":null,"keyPermissions":[{"resource_kind":"memory","level":"write","target":"every","resource_id_field":null,"only_with_field":null}],"inputSchema":{"type":"object","properties":{"project_id":{"type":"string","pattern":"^prj_[0-9a-f]{32}$"},"memory_id":{"type":"string","pattern":"^mem_[0-9a-f]{32}$"}},"required":["project_id","memory_id"],"additionalProperties":false},"outputSchema":{"type":"object","properties":{"recall":{"anyOf":[{"type":"object","properties":{"score":{"type":"number"},"mean_reciprocal_rank":{"type":"number"},"depth":{"type":"number"},"question_count":{"type":"number"},"scored_at":{"type":"string"}},"required":["score","mean_reciprocal_rank","depth","question_count","scored_at"]},{"type":"null"}],"description":"The share of saved questions for which recall returns the memory that answers them within the recall depth, or null before the first scoring."},"judgement":{"anyOf":[{"type":"object","properties":{"score":{"type":"number"},"right_count":{"type":"number"},"decision_count":{"type":"number"},"scored_at":{"type":"string"}},"required":["score","right_count","decision_count","scored_at"]},{"type":"null"}],"description":"The share of held-back labelled decisions that sorting gets right with the settings of the Memory as they are now, or null until labelled decisions exist."},"labelled_decisions":{"type":"object","properties":{"tuning_count":{"type":"number"},"held_back_count":{"type":"number"}},"required":["tuning_count","held_back_count"]},"flagged_question_count":{"type":"number","description":"How many saved questions name a memory that Himring has replaced since."},"scoring":{"type":"boolean","description":"true while Himring is scoring or tuning the Memory."},"tuning":{"type":"object","properties":{"state":{"enum":["up_to_date","new_input","queued","working"],"type":"string","description":"working while Himring tunes and scores the Memory, queued while a run waits for the pipeline, new_input when a run would use something new and nothing is queued, and up_to_date when a run would use nothing new. tune_memory refuses a run while the state is up_to_date."},"labelled_decisions_since_tuning":{"type":"number","description":"How many labelled decisions arrived since Himring last tuned the thresholds and cue weights."},"labelled_decisions_per_tuning":{"type":"number","description":"How many new labelled decisions make Himring tune by itself, with no call to tune_memory."},"saved_questions_changed":{"type":"boolean","description":"true when someone saved or deleted a saved question since the last recall scoring. Himring queues a scoring by itself for each change."},"memory_changes_since_scoring":{"anyOf":[{"type":"number"},{"type":"null"}],"description":"How many memories Himring added, changed, or removed since the last recall scoring, or null before the first scoring that counted them. The changes are new input only while saved questions exist."},"started_at":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"When the latest tuning run started."},"tuned_at":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"When the latest tuning run finished, or null before the first."}},"required":["state","labelled_decisions_since_tuning","labelled_decisions_per_tuning","saved_questions_changed","memory_changes_since_scoring","started_at","tuned_at"],"description":"What a tuning run would use that is new, and whether a run is queued or working."}},"required":["recall","judgement","labelled_decisions","flagged_question_count","scoring","tuning"]}},
  undo_learned_change: {"summary":"Undo a learned change, so that the setting returns to the value that it had before and Himring sorts the next message with that value.","tag":"memory","document":"api","access":"project","changesState":true,"dataAccess":null,"keyPermissions":[{"resource_kind":"memory","level":"write","target":"every","resource_id_field":null,"only_with_field":null}],"inputSchema":{"type":"object","properties":{"project_id":{"type":"string","pattern":"^prj_[0-9a-f]{32}$"},"memory_id":{"type":"string","pattern":"^mem_[0-9a-f]{32}$"},"change_id":{"type":"string","pattern":"^lrn_[0-9a-f]{32}$"}},"required":["project_id","memory_id","change_id"],"additionalProperties":false},"outputSchema":{"type":"object","properties":{"id":{"type":"string"},"setting":{"type":"string","description":"The setting that Himring changed, such as confidence_threshold or cue_weights.author_kind.agent."},"from_value":{"type":"number"},"to_value":{"type":"number"},"tuning_decisions":{"type":"number","description":"How many labelled decisions Himring tuned the change on."},"held_back_decisions":{"type":"number","description":"How many held-back labelled decisions checked the change."},"held_back_right_before":{"type":"number"},"held_back_right_after":{"type":"number"},"created_at":{"type":"string"},"undone_at":{"anyOf":[{"type":"string"},{"type":"null"}]}},"required":["id","setting","from_value","to_value","tuning_decisions","held_back_decisions","held_back_right_before","held_back_right_after","created_at","undone_at"]}},
